function floorAndCeil(root, x) {
  let floor = -1, ceil = -1;
  let node = root;
  while (node !== null) {
    if (node.val === x) return [x, x];     // x itself is both
    if (node.val < x) {
      floor = node.val;                    // a floor candidate; bigger ones are to the right
      node = node.right;
    } else {
      ceil = node.val;                     // a ceil candidate; smaller ones are to the left
      node = node.left;
    }
  }
  return [floor, ceil];
}

